Q: Hide navbar and sidebar on &#39;login page&#39;, but show them on other pages A: <p>I was able to solve this, using useLocation(),</p>
<pre><code>App.jsx
function App() {
  const location = useLocation();
  return (
    &lt;&gt;
      &lt;div&gt;
        {location.pathname != &quot;/login&quot; &amp;&amp; &lt;Navbar /&gt;}
        &lt;Routes&gt;
          &lt;Route path=&quot;/&quot; element={&lt;Home /&gt;} /&gt;
          &lt;Route path=&quot;/about&quot; element={&lt;About /&gt;} /&gt;
          &lt;Route path=&quot;/contact&quot; element={&lt;Contact /&gt;} /&gt;
          &lt;Route path=&quot;/login&quot; element={&lt;Login /&gt;} /&gt;
        &lt;/Routes&gt;
      &lt;/div&gt;
    &lt;/&gt;
  );
}
</code></pre>
<p>I had to remove BrowserRouter from App.jsx, import it in main.jsx, as it was showing this error
useLocation() may be used only in the context of a </p>
<pre><code>import { StrictMode } from &quot;react&quot;;
import { createRoot } from &quot;react-dom/client&quot;;
import { BrowserRouter } from &quot;react-router-dom&quot;;
import &quot;./index.css&quot;;
import App from &quot;./App.jsx&quot;;

createRoot(document.getElementById(&quot;root&quot;)).render(
  &lt;StrictMode&gt;
    &lt;BrowserRouter&gt;
      &lt;App /&gt;
    &lt;/BrowserRouter&gt;
  &lt;/StrictMode&gt;,
);
</code></pre>
